//! Deserializes sync plans in the format generated by packages/sync-rules/src/sync_plan/serialize.ts.
//!
//! Expressions in table processors can reference table-valued functions by their index. Since we
//! can't rely on the `tableValuedFunctions` key appearing before expressions in the JSON object, we
//! first deserialize structures mirroring the TypeScript definitions and then map the into plan
//! structures.

use std::{borrow::Cow, sync::Arc};

use serde::{Deserialize, Deserializer, de::Error};

use crate::sync_plan::{
    HydratedSource, ReplicationEmbedder,
    expression::{SqlExpression, TableValuedFunction},
    plan::{
        ColumnSource, EventDescriptor, RowProjection, StreamDataSource,
        StreamParameterIndexLookupCreator, TableProcessor, TableProcessorData,
        TableProcessorExpression, TableProcessorTableValuedFunction,
        TableProcessorTableValuedFunctionOutput,
    },
    table_pattern::{NameMatcher, TablePattern},
};

/// Additional context needed to deserialize Sync Plans.
#[derive(Clone, Copy)]
pub struct DeserializeSyncPlan<'a> {
    /// The default connection tag to use in table patterns when they don't specify one.
    pub default_connection_tag: &'a str,
    /// The default schema to match on when a table pattern doesn't specify one.
    pub default_schema: &'a str,
}

impl<'a> DeserializeSyncPlan<'a> {
    /// Deserializes a serialized data source (defining which buckets a row is put into and which
    /// output document is created).
    pub fn data_source<D: Deserializer<'a>, E: ReplicationEmbedder>(
        self,
        id: Arc<E::BucketId>,
        deserializer: D,
    ) -> Result<HydratedSource<E>, D::Error> {
        let raw = SerializedDataSource::deserialize(deserializer)?;
        let mapped = raw.resolve(self).map_err(D::Error::custom)?;

        Ok(HydratedSource::Bucket { id, source: mapped })
    }

    /// Deserializes a parameter index lookup creator.
    pub fn parameter_source<D: Deserializer<'a>, E: ReplicationEmbedder>(
        self,
        id: Arc<E::ParameterId>,
        deserializer: D,
    ) -> Result<HydratedSource<E>, D::Error> {
        let raw = SerializedParameterIndexLookupCreator::deserialize(deserializer)?;
        let mapped = raw.resolve(self).map_err(D::Error::custom)?;

        Ok(HydratedSource::Parameter { id, source: mapped })
    }

    /// Deserializes an event source. This currently only decodes the tables it matches on.
    pub fn event_source<D: Deserializer<'a>, E: ReplicationEmbedder>(
        self,
        id: Arc<E::EventId>,
        deserializer: D,
    ) -> Result<HydratedSource<E>, D::Error> {
        let raw = SerializedEventDescriptor::deserialize(deserializer)?;
        let mapped = raw.resolve(self).map_err(D::Error::custom)?;

        Ok(HydratedSource::Event {
            id,
            descriptor: mapped,
        })
    }
}

type SerializedExpression<'a> = SqlExpression<SerializedTableProcessorData<'a>>;

/// A `ImplicitSchemaTablePattern` as serialized by `serializeTablePattern`.
#[derive(Deserialize)]
struct SerializedTablePattern {
    connection: Option<String>,
    schema: Option<NameMatcher>,
    table: NameMatcher,
}

impl SerializedTablePattern {
    fn resolve(self, context: DeserializeSyncPlan) -> TablePattern {
        TablePattern {
            connection_tag: self
                .connection
                .unwrap_or_else(|| context.default_connection_tag.to_owned()),
            schema: self
                .schema
                .unwrap_or_else(|| NameMatcher::from_string(context.default_schema.to_owned())),
            table: self.table,
        }
    }
}

#[derive(Deserialize)]
struct SerializedPartitionKey<'a> {
    #[serde(borrow)]
    expr: SerializedExpression<'a>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SerializedTableValuedFunction<'a> {
    function_name: TableValuedFunction,
    #[serde(borrow)]
    function_inputs: Vec<SerializedExpression<'a>>,
}

/// Fields shared by `SerializedDataSource`, `SerializedParameterIndexLookupCreator` and `SerializedEventRowEvaluator`.
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SerializedTableProcessor<'a> {
    table: SerializedTablePattern,
    #[serde(borrow)]
    filters: Vec<SerializedExpression<'a>>,
    #[serde(borrow)]
    table_valued_functions: Vec<SerializedTableValuedFunction<'a>>,
    #[serde(borrow)]
    partition_by: Vec<SerializedPartitionKey<'a>>,
}

impl SerializedTableProcessor<'_> {
    fn resolve(self, context: DeserializeSyncPlan) -> Result<TableProcessor, String> {
        let mut table_valued_functions = Vec::with_capacity(self.table_valued_functions.len());

        for function in self.table_valued_functions {
            let mapped = Arc::new(TableProcessorTableValuedFunction {
                function: function.function_name,
                inputs: ResolvedTableValuedFunctions(&table_valued_functions)
                    .resolve_expressions(function.function_inputs)?,
            });

            table_valued_functions.push(mapped);
        }

        let functions = ResolvedTableValuedFunctions(&table_valued_functions);
        let filters = functions.resolve_expressions(self.filters)?;
        let parameters =
            functions.resolve_expressions(self.partition_by.into_iter().map(|key| key.expr))?;

        Ok(TableProcessor {
            source_table: self.table.resolve(context),
            filters,
            parameters,
            table_valued_functions,
        })
    }
}

/// The literal string `'star'` in a `SerializedColumnSource`.
#[derive(Deserialize)]
enum StarColumn {
    #[serde(rename = "star")]
    Star,
}

#[derive(Deserialize)]
#[serde(untagged)]
enum SerializedColumnSource<'a> {
    Star(StarColumn),
    Column {
        #[serde(borrow)]
        expr: SerializedExpression<'a>,
        alias: String,
    },
}

/// A `SerializedDataSource` as defined in serialize.ts.
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SerializedDataSource<'a> {
    #[serde(flatten, borrow)]
    processor: SerializedTableProcessor<'a>,
    output_table_name: Option<String>,
    #[serde(borrow)]
    columns: Vec<SerializedColumnSource<'a>>,
}

impl<'de> SerializedDataSource<'de> {
    fn resolve(self, context: DeserializeSyncPlan) -> Result<StreamDataSource, String> {
        let processor = self.processor.resolve(context)?;
        let functions = ResolvedTableValuedFunctions(&processor.table_valued_functions);

        // Split columns into before and after a * projection, since that information is relevant
        // when building output rows.
        let mut before = vec![];
        let mut after = vec![];
        let mut saw_star = false;

        for column in self.columns {
            match column {
                SerializedColumnSource::Star(_) => {
                    saw_star = true;
                }
                SerializedColumnSource::Column { expr, alias } => {
                    let column = ColumnSource {
                        alias,
                        expr: functions.resolve_expression(expr)?,
                    };

                    if saw_star { &mut after } else { &mut before }.push(column);
                }
            }
        }

        let projection = if saw_star {
            RowProjection::Star { before, after }
        } else {
            assert!(after.is_empty());
            RowProjection::Columns(before)
        };

        Ok(StreamDataSource {
            processor,
            projection,
            output_table_name: self.output_table_name,
        })
    }
}

/// A `SerializedParameterIndexLookupCreator` as defined in serialize.ts.
#[derive(Deserialize)]
pub struct SerializedParameterIndexLookupCreator<'a> {
    #[serde(flatten, borrow)]
    processor: SerializedTableProcessor<'a>,
    #[serde(borrow)]
    output: Vec<SerializedExpression<'a>>,
}

impl<'de> SerializedParameterIndexLookupCreator<'de> {
    fn resolve(
        self,
        context: DeserializeSyncPlan,
    ) -> Result<StreamParameterIndexLookupCreator, String> {
        let processor = self.processor.resolve(context)?;
        let outputs = ResolvedTableValuedFunctions(&processor.table_valued_functions)
            .resolve_expressions(self.output)?;

        Ok(StreamParameterIndexLookupCreator { processor, outputs })
    }
}

/// A `SerializedEventDescriptor` as defined in serialize.ts.
///
/// We only need the table patterns of source queries, the rest of the event is not evaluated here.
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SerializedEventDescriptor {
    name: String,
    source_queries: Vec<SerializedEventSourceQuery>,
}

#[derive(Deserialize)]
struct SerializedEventSourceQuery {
    table: SerializedTablePattern,
}

impl SerializedEventDescriptor {
    fn resolve(self, context: DeserializeSyncPlan) -> Result<EventDescriptor, String> {
        Ok(EventDescriptor {
            name: self.name,
            patterns: self
                .source_queries
                .into_iter()
                .map(|query| query.table.resolve(context))
                .collect(),
        })
    }
}

/// The table-valued functions of the [TableProcessor] being deserialized, used to resolve function
/// outputs referenced by the serialized index.
#[derive(Clone, Copy)]
struct ResolvedTableValuedFunctions<'a>(&'a [Arc<TableProcessorTableValuedFunction>]);

/// [TableProcessorData] in the format generated by `replaceFunctionReferenceWithIndex` in
/// packages/sync-rules/src/sync_plan/serialize.ts.
#[derive(Deserialize)]
#[serde(untagged)]
enum SerializedTableProcessorData<'a> {
    Column {
        column: String,
    },
    Metadata {
        metadata: RowMetadataKind,
    },
    TableValuedFunctionOutput {
        function: usize,
        #[serde(rename = "outputName", borrow)]
        output_name: Cow<'a, str>,
    },
}

#[derive(Deserialize)]
#[serde(rename_all = "snake_case")]
enum RowMetadataKind {
    Schema,
    TableName,
    TableSuffix,
}

impl ResolvedTableValuedFunctions<'_> {
    fn resolve(self, data: SerializedTableProcessorData) -> Result<TableProcessorData, String> {
        Ok(match data {
            SerializedTableProcessorData::Column { column } => {
                TableProcessorData::ColumnInSourceRow(column)
            }
            SerializedTableProcessorData::Metadata { metadata } => match metadata {
                RowMetadataKind::Schema => TableProcessorData::SchemaName,
                RowMetadataKind::TableSuffix => TableProcessorData::TableSuffix,
                RowMetadataKind::TableName => TableProcessorData::TableName,
            },
            SerializedTableProcessorData::TableValuedFunctionOutput {
                function,
                output_name,
            } => {
                let function = self
                    .0
                    .get(function)
                    .ok_or_else(|| format!("invalid table-valued function index {function}"))?;
                let output_slot = function
                    .function
                    .output_columns()
                    .iter()
                    .position(|column| *column == output_name)
                    .ok_or_else(|| {
                        format!("table-valued function has no output named {output_name:?}")
                    })?;

                TableProcessorData::TableValuedFunction(TableProcessorTableValuedFunctionOutput {
                    function: function.clone(),
                    output_slot,
                })
            }
        })
    }

    fn resolve_expression(
        self,
        expr: SerializedExpression,
    ) -> Result<TableProcessorExpression, String> {
        expr.try_map(&mut |data| self.resolve(data))
    }

    fn resolve_expressions<'a>(
        self,
        exprs: impl IntoIterator<Item = SerializedExpression<'a>>,
    ) -> Result<Vec<TableProcessorExpression>, String> {
        exprs
            .into_iter()
            .map(|expr| self.resolve_expression(expr))
            .collect()
    }
}
